import * as React from "react";
import { Box, Grid, Card, CardContent, Typography, CardActionArea } from "@mui/material";

interface HomePageProps {
  onSelect: (page: string) => void;
}

const HomePage = ({ onSelect }: HomePageProps) => {
  const cards = [
    { label: "Venues", value: "venues" },
    { label: "Hair", value: "hair" },
    { label: "Makeup", value: "makeup" },
    { label: "Photographers", value: "photographers" },
    { label: "Music", value: "music" },
    { label: "Florist", value: "florist" },
    { label: "Dresser", value: "dresser" },
    { label: "Planner", value: "planner" },
  ];

  // Handle card click event
  const handleCardClick = (page: string) => {
    onSelect(page);  // Trigger page change via the parent
  };

  return (
    <Box sx={{ padding: 2 }}>
      <Grid container spacing={2}>
        {cards.map((card) => (
          <Grid item xs={6} sm={4} md={3} key={card.value}> {/* Two columns on mobile and 3 on tablet/desktop */}
            <Card sx={{ boxShadow: 3 }}>
              <CardActionArea onClick={() => handleCardClick(card.value)}>
                <CardContent>
                  <Typography variant="h6" component="div" sx={{ fontWeight: "bold" }}>
                    {card.label}
                  </Typography>
                </CardContent>
              </CardActionArea>
            </Card>
          </Grid>
        ))}
      </Grid>
      {/* Keep existing content below */}
      <Box sx={{ marginTop: 4 }}>
        <Typography variant="h4" component="div" sx={{ fontWeight: "bold", marginBottom: 2 }}>
          Welcome to Our Wedding Services
        </Typography>
        <Typography variant="body1" sx={{ marginBottom: 2 }}>
          Discover the best wedding venues, photographers, makeup artists, and more to make your special day unforgettable. Our carefully selected vendors will ensure your wedding day is exactly what you’ve always dreamed of.
        </Typography>
      </Box>
    </Box>
  );
};

export default HomePage;

